#!/usr/bin/env node
/**
 * build-engine-bundle.mjs — build the engine into the skill that ships it.
 *
 * The engine travels **inside the skill tree** (`skills/engine/`) so that
 * installing the skill installs an engine: no TypeScript toolchain, no
 * `node_modules`, no build step, no `--experimental-strip-types`. See ADR-0025.
 *
 *   node scripts/build-engine-bundle.mjs           # build + write the manifest
 *   node scripts/build-engine-bundle.mjs --check   # fail if the committed bundle is stale
 *
 * `--check` does not compare bytes against esbuild's output (minifier output can
 * shift between esbuild patch releases). It compares a fingerprint of the build
 * *inputs* — engine/ and packages/**&#47;src, the package manifests, and
 * runtime/templates (whose content is embedded in the bundle) — against the
 * fingerprint recorded in `skills/engine/bundle-manifest.json` when the bundle
 * was last built. That catches the real failure mode: source changed, bundle not
 * rebuilt. CI runs `--check`; `npm run build` refreshes both files.
 */

import { createHash } from "node:crypto";
import { chmodSync, existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import * as esbuild from "esbuild";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, "..");
const ENTRY = join(REPO_ROOT, "engine", "dapei-engine.ts");
const SKILL_DIR = join(REPO_ROOT, "skills", "engine");
const BUNDLE = join(SKILL_DIR, "dapei-engine.js");
const MANIFEST = join(SKILL_DIR, "bundle-manifest.json");

// Everything that can change what the bundle does. runtime/templates is here
// because its contents are compiled into the bundle (gen-embedded-assets).
const INPUT_ROOTS = ["engine", "runtime/templates"];
const PACKAGE_GLOBS = ["packages"];

function listFiles(dir, out = []) {
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    const abs = join(dir, name);
    if (statSync(abs).isDirectory()) listFiles(abs, out);
    else out.push(abs);
  }
  return out;
}

/** Content fingerprint of every build input, as `path:sha256` lines hashed together. */
function inputsFingerprint() {
  const inputs = [];
  for (const root of INPUT_ROOTS) {
    for (const abs of listFiles(join(REPO_ROOT, root))) {
      if (abs.endsWith(".ts") || abs.endsWith(".json") || abs.endsWith(".yaml") || abs.endsWith(".template") || abs.endsWith(".md")) {
        inputs.push(abs);
      }
    }
  }
  for (const pkgRoot of PACKAGE_GLOBS) {
    const base = join(REPO_ROOT, pkgRoot);
    if (!existsSync(base)) continue;
    for (const pkg of readdirSync(base)) {
      const src = join(base, pkg, "src");
      if (existsSync(src)) {
        for (const abs of listFiles(src)) {
          if (/\.(ts|ya?ml)$/.test(abs)) inputs.push(abs);
        }
      }
      const manifest = join(base, pkg, "package.json");
      if (existsSync(manifest)) inputs.push(manifest);
    }
  }
  const lines = inputs
    .sort()
    .map((abs) => {
      const rel = relative(REPO_ROOT, abs).split(sep).join("/");
      return `${rel}:${createHash("sha256").update(readFileSync(abs)).digest("hex")}`;
    });
  return createHash("sha256").update(lines.join("\n")).digest("hex");
}

function fail(msg) {
  console.error(`[build:bundle] FAIL: ${msg}`);
  process.exit(1);
}

const fingerprint = inputsFingerprint();
const check = process.argv.includes("--check");

if (check) {
  if (!existsSync(BUNDLE)) fail(`${relative(REPO_ROOT, BUNDLE)} is missing — run \`npm run build\` and commit it`);
  if (!existsSync(MANIFEST)) fail(`${relative(REPO_ROOT, MANIFEST)} is missing — run \`npm run build\` and commit it`);
  const recorded = JSON.parse(readFileSync(MANIFEST, "utf8"));
  if (recorded.inputs_sha256 !== fingerprint) {
    fail(
      `the committed engine bundle is stale: build inputs changed since it was built.\n` +
        `  recorded ${recorded.inputs_sha256}\n  current  ${fingerprint}\n` +
        `  run \`npm run build\` and commit skills/engine/dapei-engine.js + bundle-manifest.json`
    );
  }
  console.log("[build:bundle] OK — the committed bundle matches the current sources");
  process.exit(0);
}

const result = await esbuild.build({
  entryPoints: [ENTRY],
  bundle: true,
  platform: "node",
  format: "esm",
  outfile: BUNDLE,
  external: ["node:*"],
  minify: true,
  logLevel: "warning",
  metafile: true
});

const bytes = statSync(BUNDLE).size;
chmodSync(BUNDLE, 0o755);
writeFileSync(
  MANIFEST,
  `${JSON.stringify(
    {
      comment:
        "Generated by scripts/build-engine-bundle.mjs — records the build inputs the committed bundle came from. CI verifies it with `npm run check:bundle`.",
      bundle: "skills/engine/dapei-engine.js",
      bytes,
      entry: "engine/dapei-engine.ts",
      node: ">=20 (no type-stripping flags required)",
      inputs_sha256: fingerprint,
      output_count: Object.keys(result.metafile.outputs).length
    },
    null,
    2
  )}\n`
);

console.log(`[build:bundle] wrote skills/engine/dapei-engine.js (${bytes} bytes) + bundle-manifest.json`);
